import{F as a,b as r,c as e,ah as l}from"./chunks/framework.CCFHGMHW.js";const d=JSON.parse('{"title":"GitHub 热门 AI 项目（2026 年第 45 周）","description":"","frontmatter":{"title":"GitHub 热门 AI 项目（2026 年第 45 周）","date":"2026/11/02","author":"花木凋零成兰","tags":["GitHub","AI","周刊","Agent"],"hiddenCover":true,"head":[["link",{"rel":"canonical","href":"https://imulan.top/GitHub%E7%9B%B8%E5%85%B3/2026/GitHub%E7%83%AD%E9%97%A8AI%E9%A1%B9%E7%9B%AE%EF%BC%882026%E5%B9%B4%E7%AC%AC45%E5%91%A8%EF%BC%89.html"}]]},"headers":[],"relativePath":"GitHub相关/2026/GitHub热门AI项目（2026年第45周）.md","filePath":"GitHub相关/2026/GitHub热门AI项目（2026年第45周）.md","lastUpdated":1793577819000}'),i={name:"GitHub相关/2026/GitHub热门AI项目（2026年第45周）.md"};function n(o,t,s,g,u,h){return r(),e("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1793577600000"},[...t[0]||(t[0]=[l('<h1 id="github-热门-ai-项目-2026-年第-45-周" tabindex="-1">GitHub 热门 AI 项目（2026 年第 45 周） <a class="header-anchor" href="#github-热门-ai-项目-2026-年第-45-周" aria-label="Permalink to &quot;GitHub 热门 AI 项目（2026 年第 45 周）&quot;">​</a></h1><blockquote><p>数据来源：GitHub Trending 总榜，快照时间为 2026 年 11 月 2 日早间；Star 总数取仓库 API，周增量取榜单页面。</p></blockquote><p>本周主线：<strong>Agent 工具开始把“生成结果”转成可检查的工作规范</strong>——设计技能、SEO 审计、开发方法论与安全审计分别约束网页观感、站点检查和代码交付；与此同时，跨会话记忆、轻量 IDE 与远程控制继续完善 Agent 工作台。金融交易多 Agent 项目也进入榜单，但更适合作为研究系统观察对象，不是投资建议。</p><h2 id="项目清单" tabindex="-1">项目清单 <a class="header-anchor" href="#项目清单" aria-label="Permalink to &quot;项目清单&quot;">​</a></h2><h3 id="_1-hallmark-nutlope-hallmark" tabindex="-1">1. Hallmark（Nutlope/hallmark） <a class="header-anchor" href="#_1-hallmark-nutlope-hallmark" aria-label="Permalink to &quot;1. Hallmark（Nutlope/hallmark）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/Nutlope/hallmark" target="_blank" rel="noreferrer">https://github.com/Nutlope/hallmark</a></li><li><strong>Star 数</strong>：44,848（本周 +12,062）</li><li><strong>项目简介</strong>：为 Claude Code、Cursor 和 Codex 提供网页设计技能，结合主题选择、页面任务和版式检查，适合用编码 Agent 起草活动页或产品页时减少模板化设计。</li><li><strong>本周热度亮点</strong>：总榜周新增 12,062 Star；围绕 AI 生成网页“看起来千篇一律”的改进需求获得显著关注。</li><li><strong>技术栈</strong>：CSS</li></ul><h3 id="_2-impeccable-pbakaus-impeccable" tabindex="-1">2. Impeccable（pbakaus/impeccable） <a class="header-anchor" href="#_2-impeccable-pbakaus-impeccable" aria-label="Permalink to &quot;2. Impeccable（pbakaus/impeccable）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/pbakaus/impeccable" target="_blank" rel="noreferrer">https://github.com/pbakaus/impeccable</a></li><li><strong>Star 数</strong>：99,289（本周 +12,031）</li><li><strong>项目简介</strong>：为多种编码 Agent 提供设计指令与审查命令，可在已有网页原型上执行润色、批评和审计；README 给出 <code>npx impeccable install</code> 安装方式。</li><li><strong>本周热度亮点</strong>：总榜周新增 12,031 Star，设计审查型 Agent 技能与网页反模板化成为本周热点。</li><li><strong>技术栈</strong>：Rust</li></ul><h3 id="_3-claude-seo-agricidaniel-claude-seo" tabindex="-1">3. Claude SEO（AgriciDaniel/claude-seo） <a class="header-anchor" href="#_3-claude-seo-agricidaniel-claude-seo" aria-label="Permalink to &quot;3. Claude SEO（AgriciDaniel/claude-seo）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/AgriciDaniel/claude-seo" target="_blank" rel="noreferrer">https://github.com/AgriciDaniel/claude-seo</a></li><li><strong>Star 数</strong>：25,517（本周 +4,814）</li><li><strong>项目简介</strong>：Claude Code 的 SEO 审计插件，覆盖技术 SEO、结构化数据、本地与国际化 SEO 等，适合对网站进行发布前检查；README 列出 26 个子技能及可选实时数据扩展。</li><li><strong>本周热度亮点</strong>：总榜周新增 4,814 Star；SEO 工作流开始把传统搜索与 AI 搜索可见性纳入同一套 Agent 检查。</li><li><strong>技术栈</strong>：Python</li></ul><h3 id="_4-claude-mem-thedotmack-claude-mem" tabindex="-1">4. Claude-Mem（thedotmack/claude-mem） <a class="header-anchor" href="#_4-claude-mem-thedotmack-claude-mem" aria-label="Permalink to &quot;4. Claude-Mem（thedotmack/claude-mem）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/thedotmack/claude-mem" target="_blank" rel="noreferrer">https://github.com/thedotmack/claude-mem</a></li><li><strong>Star 数</strong>：109,199（本周 +4,575）</li><li><strong>项目简介</strong>：捕获编码 Agent 的会话活动、压缩上下文并在后续会话注入相关信息，README 声明支持 Codex、Hermes、OpenCode 等工具；适合跨会话继续开发时减少重复交代背景。</li><li><strong>本周热度亮点</strong>：总榜周新增 4,575 Star；多 Agent 共用的长期上下文仍是高关注方向。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h3 id="_5-security-audit-skill-cloudflare-security-audit-skill" tabindex="-1">5. Security Audit Skill（cloudflare/security-audit-skill） <a class="header-anchor" href="#_5-security-audit-skill-cloudflare-security-audit-skill" aria-label="Permalink to &quot;5. Security Audit Skill（cloudflare/security-audit-skill）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/cloudflare/security-audit-skill" target="_blank" rel="noreferrer">https://github.com/cloudflare/security-audit-skill</a></li><li><strong>Star 数</strong>：56,341（本周 +11,908）</li><li><strong>项目简介</strong>：将编码 Agent 组织成多阶段代码安全审计流程，包含覆盖度检查、候选问题复核与结构化报告，适合对单个代码库进行发布前审查。</li><li><strong>本周热度亮点</strong>：总榜周新增 11,908 Star；本项目也出现在第 44 周榜单，安全审计与独立复核方向延续关注。</li><li><strong>技术栈</strong>：JavaScript</li></ul><h3 id="_6-superpowers-obra-superpowers" tabindex="-1">6. Superpowers（obra/superpowers） <a class="header-anchor" href="#_6-superpowers-obra-superpowers" aria-label="Permalink to &quot;6. Superpowers（obra/superpowers）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/obra/superpowers" target="_blank" rel="noreferrer">https://github.com/obra/superpowers</a></li><li><strong>Star 数</strong>：310,621（本周 +5,636）</li><li><strong>项目简介</strong>：把可组合技能和开发方法论用于编码 Agent，覆盖从任务澄清到软件实现的工作步骤，适合希望为 Agent 增加相对固定工程流程的开发者。</li><li><strong>本周热度亮点</strong>：总榜周新增 5,636 Star；“方法论加技能”的 Agent 工作流继续获得关注。</li><li><strong>技术栈</strong>：Shell</li></ul><h3 id="_7-thinkrail-jetbrains-thinkrail" tabindex="-1">7. ThinkRail（JetBrains/thinkrail） <a class="header-anchor" href="#_7-thinkrail-jetbrains-thinkrail" aria-label="Permalink to &quot;7. ThinkRail（JetBrains/thinkrail）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/JetBrains/thinkrail" target="_blank" rel="noreferrer">https://github.com/JetBrains/thinkrail</a></li><li><strong>Star 数</strong>：6,964（本周 +5,738）</li><li><strong>项目简介</strong>：JetBrains 孵化项目，以 Pi 编码 Agent 为基础构建轻量 IDE，包含隔离工作区、项目知识与可复用技能，适合观察 Agent IDE 如何沉淀项目上下文。</li><li><strong>本周热度亮点</strong>：总榜周新增 5,738 Star；轻量 IDE 与项目级持久知识的组合受到关注。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h3 id="_8-t3-code-pingdotgg-t3code" tabindex="-1">8. T3 Code（pingdotgg/t3code） <a class="header-anchor" href="#_8-t3-code-pingdotgg-t3code" aria-label="Permalink to &quot;8. T3 Code（pingdotgg/t3code）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/pingdotgg/t3code" target="_blank" rel="noreferrer">https://github.com/pingdotgg/t3code</a></li><li><strong>Star 数</strong>：37,896（本周 +3,718）</li><li><strong>项目简介</strong>：用移动端、网页和桌面界面控制本机已配置的编码 Agent；需要先在本机安装并登录对应 Agent CLI，适合需要远程查看或管理开发会话的场景。</li><li><strong>本周热度亮点</strong>：总榜周新增 3,718 Star；该项目也出现在第 44 周榜单，多端远程控制本地 Agent 的方向延续关注。</li><li><strong>技术栈</strong>：TypeScript</li></ul><h3 id="_9-karpathy-inspired-claude-code-guidelines-multica-ai-andrej-karpathy-skills" tabindex="-1">9. Karpathy-Inspired Claude Code Guidelines（multica-ai/andrej-karpathy-skills） <a class="header-anchor" href="#_9-karpathy-inspired-claude-code-guidelines-multica-ai-andrej-karpathy-skills" aria-label="Permalink to &quot;9. Karpathy-Inspired Claude Code Guidelines（multica-ai/andrej-karpathy-skills）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/multica-ai/andrej-karpathy-skills" target="_blank" rel="noreferrer">https://github.com/multica-ai/andrej-karpathy-skills</a></li><li><strong>Star 数</strong>：227,979（本周 +4,277）</li><li><strong>项目简介</strong>：以单份 <code>CLAUDE.md</code> 汇总编码 Agent 常见失误及约束建议，例如避免未经确认的假设、过度设计和无关改动；适合检查项目指令如何约束 Agent 行为。</li><li><strong>本周热度亮点</strong>：总榜周新增 4,277 Star；轻量级提示规范与 Agent 行为边界成为讨论焦点。</li><li><strong>技术栈</strong>：未取得（GitHub 仓库 API 未返回主要语言）</li></ul><h3 id="_10-tradingagents-tauricresearch-tradingagents" tabindex="-1">10. TradingAgents（TauricResearch/TradingAgents） <a class="header-anchor" href="#_10-tradingagents-tauricresearch-tradingagents" aria-label="Permalink to &quot;10. TradingAgents（TauricResearch/TradingAgents）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/TauricResearch/TradingAgents" target="_blank" rel="noreferrer">https://github.com/TauricResearch/TradingAgents</a></li><li><strong>Star 数</strong>：119,517（本周 +5,483）</li><li><strong>项目简介</strong>：多 Agent 金融交易研究框架，仓库关联研究论文，可用于学习不同角色 Agent 如何协作分析；不构成交易策略有效性证明或投资建议。</li><li><strong>本周热度亮点</strong>：总榜周新增 5,483 Star；金融分析与多 Agent 协作的结合进入高关注项目。</li><li><strong>技术栈</strong>：Python</li></ul><h3 id="_11-agent-skills-anthropics-skills" tabindex="-1">11. Agent Skills（anthropics/skills） <a class="header-anchor" href="#_11-agent-skills-anthropics-skills" aria-label="Permalink to &quot;11. Agent Skills（anthropics/skills）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/anthropics/skills" target="_blank" rel="noreferrer">https://github.com/anthropics/skills</a></li><li><strong>Star 数</strong>：186,354（本周 +2,389）</li><li><strong>项目简介</strong>：Anthropic 发布的技能示例集合，展示如何用指令、脚本和资源让 Claude 执行文档、技术与企业工作任务，可作为设计专用 Agent 技能的参考。</li><li><strong>本周热度亮点</strong>：总榜周新增 2,389 Star；官方技能样例继续扩展 Agent 的可复用任务边界。</li><li><strong>技术栈</strong>：Python</li></ul><h3 id="_12-everything-claude-code-affaan-m-ecc" tabindex="-1">12. Everything Claude Code（affaan-m/ECC） <a class="header-anchor" href="#_12-everything-claude-code-affaan-m-ecc" aria-label="Permalink to &quot;12. Everything Claude Code（affaan-m/ECC）&quot;">​</a></h3><ul><li><strong>仓库地址</strong>：<a href="https://github.com/affaan-m/ECC" target="_blank" rel="noreferrer">https://github.com/affaan-m/ECC</a></li><li><strong>Star 数</strong>：294,780（本周 +6,380）</li><li><strong>项目简介</strong>：面向 Claude Code、Codex、OpenCode 等工具的 Agent 工作流集合，涵盖技能、记忆、安全与研究优先开发实践，适合比较不同工具可共享的工程约定。</li><li><strong>本周热度亮点</strong>：总榜周新增 6,380 Star；跨编码 Agent 的技能与工作流整合受到关注。</li><li><strong>技术栈</strong>：JavaScript</li></ul><h2 id="本周趋势总结" tabindex="-1">本周趋势总结 <a class="header-anchor" href="#本周趋势总结" aria-label="Permalink to &quot;本周趋势总结&quot;">​</a></h2><ol><li><strong>设计与质量检查成为 Agent 技能的显性场景</strong>：Hallmark、Impeccable 与 Claude SEO 分别处理网页设计、设计审查和站点可见性；Security Audit Skill 把独立复核带入代码安全审计。</li><li><strong>Agent 工作环境继续扩展</strong>：Claude-Mem 管理跨会话上下文，ThinkRail 探索轻量 IDE，T3 Code 提供本地 Agent 的多端控制入口。</li><li><strong>可复用方法与多 Agent 研究并行</strong>：Superpowers、Anthropic Skills 与 ECC 提供技能/流程样例；TradingAgents 展示多 Agent 在金融研究中的组织方式，不能据此推断实际投资收益。</li></ol><blockquote><p>注：Star 总数为仓库 API 读取值，周增量为 GitHub Trending 页面快照值；快照时间为 2026 年 11 月 2 日早间，仅供观察热度，不代表质量或适配性。 <em>（内容由AI生成，仅供参考）</em></p></blockquote>',31)])])}const p=a(i,[["render",n]]);export{d as __pageData,p as default};
